              is_shoppable: false,
              facebook_posts: [],
              created_at: 1614233024,
              description:
                'Jalapeños are the perfect chilies: they\'re mild but boy, do they pack a flavor-punch. They\'re also extremely delectable when paired with cheese and bacon. Don\'t believe us? Try the <a href="https://tasty.co/recipe/bacon-jalapeno-popper-pinwheels">Bacon Jalapeño Popper Pinwheels</a>. You can also spice up your regular <a href="https://tasty.co/recipe/dutch-oven-jalapeno-cheddar-bread">morning toast</a> with this little gem. Still need more? Why not make a bottle of the <a href="https://tasty.co/recipe/jalapeno-mild-sauce">Jalapeño Mild Sauce</a> that goes with practically everything? It\'s time to get your spice on! ',
