              beauty_url: null,
              slug: "ring-recipes-for-party-animals",
              description:
                "What's the best part of a party? The food (shh, we won't tell your guests if you won't). And when it's food that everyone can share, it's really a party. Enter: ring recipes From a cheesy <a href=\"https://tasty.co/recipe/bacon-wrapped-burger-ring\">Bacon-Wrapped Burger Ring</a> to an irresistible <a href=\"https://tasty.co/recipe/bbq-chicken-monkey-bread-ring\">BBQ Chicken Monkey Bread Ring</a>, you can try all of them out! What are you waiting for? Let's party.",
